import{_ as o,a0 as p,w as d,s as r,I as t,x as l,a1 as e,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"搭建私有云：OwnCloud | LCTT x X-CMD","titleTemplate":false,"description":"搭建私有云：OwnCloud | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"搭建私有云：OwnCloud | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"搭建私有云：OwnCloud | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180129 Create your own personal Cloud- Install OwnCloud","title":"搭建私有云：OwnCloud","tag":"201803","desc":""},"relativePath":"201803/20180129 Create your own personal Cloud- Install OwnCloud.md","filePath":"[post].md"}'),u={name:"201803/20180129 Create your own personal Cloud- Install OwnCloud.md"};function h(g,s,c,b,k,C){const i=p("Link");return d(),r("div",null,[s[23]||(s[23]=t("h1",{id:"搭建私有云-owncloud",tabindex:"-1"},[l("搭建私有云：OwnCloud "),t("a",{class:"header-anchor",href:"#搭建私有云-owncloud","aria-label":"Permalink to “搭建私有云：OwnCloud”"},"​")],-1)),s[24]||(s[24]=t("p",null,"所有人都在討論雲。儘管市面上有很多為我們提供雲存儲和其他雲服務的主要服務商，但是我們還是可以為自己搭建一個私有云。",-1)),s[25]||(s[25]=t("p",null,"在本教程中，我們將討論如何利用 OwnCloud 搭建私有云。OwnCloud 是一個可以安裝在我們 Linux 設備上的 web 應用程序，能夠存儲和用我們的數據提供服務。OwnCloud 可以分享日曆、聯繫人和書籤，共享音/視頻流等等。",-1)),s[26]||(s[26]=t("p",null,"本教程中，我們使用的是 CentOS 7 系統，但是本教程同樣適用於其他 Linux 發行版中安裝 OwnCloud。讓我們開始安裝 OwnCloud 並且做一些準備工作，",-1)),t("ul",null,[t("li",null,[s[1]||(s[1]=l("推薦閲讀：",-1)),e(i,{href:"http://linuxtechlab.com/apache-as-reverse-proxy-centos-rhel/"},{default:n(()=>[...s[0]||(s[0]=[l("如何在 CentOS & RHEL 上使用 Apache 作為反向代理服務器",-1)])]),_:1})]),t("li",null,[s[3]||(s[3]=l("同時推薦：",-1)),e(i,{href:"http://linuxtechlab.com/linux-server-glances-monitoring-tool/"},{default:n(()=>[...s[2]||(s[2]=[l("實時 Linux 服務器監測和 GLANCES 監測工具",-1)])]),_:1})])]),s[27]||(s[27]=t("h3",{id:"預備",tabindex:"-1"},[l("預備 "),t("a",{class:"header-anchor",href:"#預備","aria-label":"Permalink to “預備”"},"​")],-1)),t("ul",null,[t("li",null,[s[6]||(s[6]=l("我們需要在機器上配置 LAMP。參照閲讀我們的文章《",-1)),e(i,{href:"http://linuxtechlab.com/easiest-guide-creating-lamp-server/"},{default:n(()=>[...s[4]||(s[4]=[l("在 CentOS/RHEL 上配置 LAMP 服務器最簡單的教程",-1)])]),_:1}),s[7]||(s[7]=l("》 & 《",-1)),e(i,{href:"http://linuxtechlab.com/install-lamp-stack-on-ubuntu/"},{default:n(()=>[...s[5]||(s[5]=[l("在 Ubuntu 搭建 LAMP",-1)])]),_:1}),s[8]||(s[8]=l("》。",-1))]),s[9]||(s[9]=a("<li>我們需要在自己的設備裏安裝這些包，<code>php-mysql</code>、 <code>php-json</code>、 <code>php-xml</code>、 <code>php-mbstring</code>、 <code>php-zip</code>、 <code>php-gd</code>、 <code>curl、 </code>php-curl<code> 、</code>php-pdo`。使用包管理器安裝它們。</li>",1))]),s[28]||(s[28]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install php-mysql php-json php-xml php-mbstring php-zip php-gd curl php-curl php-pdo</span></span></code></pre></div><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>安裝 OwnCloud，我們現在需要在服務器上下載 OwnCloud 安裝包。使用下面的命令從官方網站下載最新的安裝包（10.0.4-1）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://download.owncloud.org/community/owncloud-10.0.4.tar.bz2</span></span></code></pre></div><p>使用下面的命令解壓：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvf owncloud-10.0.4.tar.bz2</span></span></code></pre></div><p>現在，將所有解壓後的文件移動至 <code>/var/www/html</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv owncloud/* /var/www/html</span></span></code></pre></div><p>下一步，我們需要在 Apache 的配置文件 <code>httpd.conf</code> 上做些修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /etc/httpd/conf/httpd.conf</span></span></code></pre></div><p>更改下面的選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AllowOverride All</span></span></code></pre></div><p>保存該文件，並修改 OwnCloud 文件夾的文件權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chown -R apache:apache /var/www/html/</span></span>
<span class="line"><span>$ sudo chmod 777 /var/www/html/config/</span></span></code></pre></div><p>然後重啓 Apache 服務器執行修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart httpd</span></span></code></pre></div><p>現在，我們需要在 MariaDB 上創建一個數據庫，保存來自 OwnCloud 的數據。使用下面的命令創建資料庫和資料庫用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>MariaDB [(none)] &gt; create database owncloud;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; GRANT ALL ON owncloud.* TO ocuser@localhost IDENTIFIED BY &#39;owncloud&#39;;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; flush privileges;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; exit</span></span></code></pre></div><p>服務器配置部分完成後，現在我們可以在網頁瀏覽器上訪問 OwnCloud。打開瀏覽器，輸入您的服務器 IP 地址，我這邊的服務器是 10.20.30.100：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud1-compressor.jpg?resize=400%2C647" alt="安裝 owncloud"></p><p>一旦 URL 加載完畢，我們將呈現上述頁面。這裏，我們將創建管理員用户同時提供資料庫信息。當所有信息提供完畢，點擊“Finish setup”。</p><p>我們將被重定向到登錄頁面，在這裏，我們需要輸入先前創建的憑據：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud2-compressor1.jpg?resize=876%2C541" alt="安裝 owncloud"></p><p>認證成功之後，我們將進入 OwnCloud 面板：</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud3-compressor1.jpg?resize=981%2C474" alt="安裝 owncloud"></p><p>我們可以使用手機應用程序，同樣也可以使用網頁界面更新我們的數據。現在，我們已經有自己的私有云了，同時，關於如何安裝 OwnCloud 創建私有云的教程也進入尾聲。請在評論區留下自己的問題或建議。</p><hr>`,27)),t("p",null,[s[11]||(s[11]=l("via: ",-1)),e(i,{href:"http://linuxtechlab.com/create-personal-cloud-install-owncloud/"},{default:n(()=>[...s[10]||(s[10]=[l("http://linuxtechlab.com/create-personal-cloud-install-owncloud/",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=l("作者：",-1)),e(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>[...s[12]||(s[12]=[l("SHUSAIN",-1)])]),_:1}),s[16]||(s[16]=l(" 譯者：",-1)),e(i,{href:"https://github.com/CYLeft"},{default:n(()=>[...s[13]||(s[13]=[l("CYLeft",-1)])]),_:1}),s[17]||(s[17]=l(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[l("wxy",-1)])]),_:1})]),t("p",null,[s[20]||(s[20]=l("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[l("LCTT",-1)])]),_:1}),s[21]||(s[21]=l(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[l("Linux中國",-1)])]),_:1}),s[22]||(s[22]=l(" 榮譽推出",-1))])])}const x=o(u,[["render",h]]);export{f as __pageData,x as default};
